-- AstroUI provides the basis for configuring the AstroNvim User Interface
-- Configuration documentation can be found with `:h astroui`
-- NOTE: We highly recommend setting up the Lua Language Server (`:LspInstall lua_ls`)
--       as this provides autocomplete and documentation while editing

-- palette.lua is generated by scripts/theme.sh, like the rest of the desktop.
local p = require "palette"

-- Any name from lua/themes.lua.
local colorscheme = "github_dark_dimmed"

-- Match editor chrome (background, splits, floats, statusline) to the
-- desktop palette, whichever theme handles syntax.
local chrome = {
  Normal = { bg = p.bg },
  NormalNC = { bg = p.bg },
  NormalFloat = { bg = p.bg_alt },
  FloatBorder = { bg = p.bg_alt, fg = p.border },
  FloatTitle = { bg = p.bg_alt, fg = p.text },

  -- 1px split seams, like the window borders.
  WinSeparator = { fg = p.border, bg = p.bg },
  VertSplit = { fg = p.border, bg = p.bg },

  StatusLine = { bg = p.bg_alt, fg = p.dim },
  StatusLineNC = { bg = p.bg_alt, fg = p.muted },

  SignColumn = { bg = p.bg },
  FoldColumn = { bg = p.bg },
  EndOfBuffer = { bg = p.bg },
  LineNr = { fg = p.muted, bg = p.bg },
  CursorLineNr = { fg = p.text, bg = p.surface },
  CursorLine = { bg = p.bg_alt },
  ColorColumn = { bg = p.bg_alt },
  Folded = { bg = p.surface },
  WinBar = { bg = p.bg },
  WinBarNC = { bg = p.bg },

  Visual = { bg = p.surface_hi },

  -- Picker cursor row: by default it is the same bg as the float, so
  -- invisible.
  SnacksPickerListCursorLine = { bg = p.surface_hi },

  Pmenu = { bg = p.surface },
  PmenuSel = { bg = p.surface_hi },
  PmenuSbar = { bg = p.surface },
  PmenuThumb = { bg = p.border },

  -- Side panels some themes give their own bg.
  NeoTreeNormal = { bg = p.bg },
  NeoTreeNormalNC = { bg = p.bg },
  NeoTreeEndOfBuffer = { bg = p.bg },
  NeoTreeWinSeparator = { fg = p.border, bg = p.bg },
  WhichKeyNormal = { bg = p.bg_alt },

  -- Tab line, like the bar.
  TabLine = { bg = p.bg_alt, fg = p.muted },
  TabLineFill = { bg = p.bg_alt },
  TabLineSel = { bg = p.bg, fg = p.accent },
}

-- zenwritten only: distinguish by weight/slant/brightness, not hue. On a
-- coloured theme these would grey the syntax back out.
local mono = vim.tbl_extend("force", chrome, {
  Normal = { bg = p.bg, fg = p.text },
  NormalFloat = { bg = p.bg_alt, fg = p.text },
  Pmenu = { bg = p.surface, fg = p.text },
  PmenuSel = { bg = p.surface_hi, fg = p.accent },
  Folded = { bg = p.surface, fg = p.dim },
  WinBar = { bg = p.bg, fg = p.dim },
  WinBarNC = { bg = p.bg, fg = p.muted },

  Comment = { fg = p.muted, italic = true },

  Type = { fg = p.text, bold = true }, -- types, classes, interfaces, structs, enums: brighter + bold
  ["@type"] = { link = "Type" },
  ["@lsp.type.class"] = { link = "Type" },
  ["@lsp.type.interface"] = { link = "Type" },
  ["@lsp.type.struct"] = { link = "Type" },
  ["@lsp.type.enum"] = { link = "Type" },

  Function = { bold = true }, -- function/method names: same gray, just bold
  ["@function"] = { link = "Function" },
  ["@function.call"] = { link = "Function" },
  ["@method"] = { link = "Function" },
  ["@method.call"] = { link = "Function" },

  -- Parameters: dimmer and italic.
  ["@variable.parameter"] = { fg = p.dim, italic = true },
  ["@lsp.type.parameter"] = { link = "@variable.parameter" },
})

-- AstroUI replaces whole groups, which would wipe the theme's fg. As a
-- function it runs after the colorscheme loads, so the chrome can be merged
-- on top instead.
local function merged(overrides)
  return function()
    local out = {}
    for group, spec in pairs(overrides) do
      local current = vim.api.nvim_get_hl(0, { name = group, link = false })
      out[group] = vim.tbl_extend("force", current, spec)
    end
    return out
  end
end

---@type LazySpec
return {
  "AstroNvim/astroui",
  ---@type AstroUIOpts
  opts = {
    colorscheme = colorscheme,
    highlights = (function()
      local out = {}
      for _, theme in ipairs(require "themes") do
        out[theme.hl or theme.name] = theme.mono and mono or merged(chrome)
      end
      return out
    end)(),
    -- Icons can be configured throughout the interface
    icons = {
      -- configure the loading of the lsp in the status line
      LSPLoading1 = "⠋",
      LSPLoading2 = "⠙",
      LSPLoading3 = "⠹",
      LSPLoading4 = "⠸",
      LSPLoading5 = "⠼",
      LSPLoading6 = "⠴",
      LSPLoading7 = "⠦",
      LSPLoading8 = "⠧",
      LSPLoading9 = "⠇",
      LSPLoading10 = "⠏",
    },
  },
}
